else {
    /* need to defragment the table before inserting upfront */
    dht = hpack_dht_defrag(dht);
    wrap = dht->wrap + 1;
    head = dht->head + 1;
    dht->dte[head].addr = dht->dte[dht->front].addr - (name.len + value.len);
    dht->front = head;
}
```

